preConditionHook:
// A LEVEL REMEMBERED FROM AN EARLIER BAR. The opposite extreme of the most
// recent NOTABLE bar -- a large trend bar, the bar an earlier setup was
// entered on -- is support (long) or resistance (short), because the
// protective stops of the traders who entered there rest just beyond it. A
// bull trend bar's low is the level the bulls defend; a bear trend bar's high
// is the bears'.
//
// NOTABLE is a strong trend bar in the direction being defended: the body is
// at least bodyFraction of the bar's own range and points the right way. The
// threshold is an input rather than a literal, per the authoring brief; 0.6 is
// the corpus's settled strong-trend-bar body fraction (StrongTrendBarRun,
// ClimaxBarAtChannelLine).
//
// DECISION (the brief settles the level, not its lifetime): "the level
// persists until it is tested" is implemented as the MOST RECENT notable bar
// within recentBars, re-derived every bar, rather than a latched level with a
// consumed flag. A latch would need a tested/untested bit that no source
// defines the reset for, and the scan is expressible identically in both
// twins. The scan starts at bar 1, so the current bar can never be its own
// level.
//
// TWO TRIGGERS ON ONE LEVEL, exactly as the sources state them, and the rule
// fires on either:
//   * the LIMIT TEST -- the low comes down into the band [level,
//     level + testTicks] without breaking the level, and the close holds above
//     it;
//   * the STOP RUN -- the low probes at least runTicks BELOW the level and the
//     close still holds above it.
// The test half carries its lower edge (low at or above the level), which the
// merged pseudocode left implicit: without it the stop run would be a subset
// of the test and the second trigger would say nothing.
//
// Not TouchOfRecentExtreme or LevelTouchCount, whose levels are window
// extremes; not StopRunReversalBar, whose level is an N-bar extreme rather
// than one bar's own extreme.
//
// THE TICK is EL's own MinMove / PriceScale, VERIFIED and per-symbol constant
// for the whole run, written DIVISION-FIRST in both twins so the C++ reads
// token for token against its EasyLanguage.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration is a
// redefinition when this rule is placed twice in one strategy. Every one is
// fully assigned each bar before it is read.
tickSize = ctx.MinMove() / ctx.PriceScale();
haveUp = false;
lvlUp = 0.0;
for (int i = 1; i <= (int)recentBars; ++i) {
    if (!haveUp && el_gt(close[i], open[i])
        && el_ge(close[i] - open[i], bodyFraction * (high[i] - low[i]))) {
        lvlUp = low[i];
        haveUp = true;
    }
}
haveDn = false;
lvlDn = 0.0;
for (int i = 1; i <= (int)recentBars; ++i) {
    if (!haveDn && el_lt(close[i], open[i])
        && el_ge(open[i] - close[i], bodyFraction * (high[i] - low[i]))) {
        lvlDn = high[i];
        haveDn = true;
    }
}
testUp = haveUp && el_le(low[0], lvlUp + testTicks * tickSize) && el_ge(low[0], lvlUp);
runUp = haveUp && el_lt(low[0], lvlUp - runTicks * tickSize);
testDn = haveDn && el_ge(high[0], lvlDn - testTicks * tickSize) && el_le(high[0], lvlDn);
runDn = haveDn && el_gt(high[0], lvlDn + runTicks * tickSize);
okUp = haveUp && (testUp || runUp) && el_gt(close[0], lvlUp);
okDn = haveDn && (testDn || runDn) && el_lt(close[0], lvlDn);
